import{_ as s,o as t,c as n,ai as e}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"模板：销售跟进助理","description":"客户调研、通话后整理、CRM 更新和跟进邮件草稿，一条龙。","frontmatter":{"related":["/roles/ops-sales","/basics/drafts-first"],"template":"sales-followup","title":"模板：销售跟进助理","description":"客户调研、通话后整理、CRM 更新和跟进邮件草稿，一条龙。","section":"templates","order":8,"role":"销售跟进助理","type":"单 Bot 模板","tags":["模板","销售","CRM"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations"],"wordCount":142,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模板：销售跟进助理 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"客户调研、通话后整理、CRM 更新和跟进邮件草稿，一条龙。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/templates/sales-followup"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/templates-sales-followup-9f03e38e27.png"}],["meta",{"property":"og:image:alt","content":"模板：销售跟进助理 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"模板：销售跟进助理 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"客户调研、通话后整理、CRM 更新和跟进邮件草稿，一条龙。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/templates-sales-followup-9f03e38e27.png"}],["meta",{"name":"twitter:image:alt","content":"模板：销售跟进助理 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/templates/sales-followup"}]]},"headers":[],"relativePath":"templates/sales-followup.md","filePath":"templates/sales-followup.md","lastUpdated":1792485206000}'),l={name:"templates/sales-followup.md"};function p(o,a,i,r,c,d){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="模板-销售跟进助理" tabindex="-1">模板：销售跟进助理 <a class="header-anchor" href="#模板-销售跟进助理" aria-label="Permalink to &quot;模板：销售跟进助理&quot;">​</a></h1><ul><li><strong>角色</strong>：销售跟进助理</li><li><strong>类型</strong>：单 Bot 模板</li><li><strong>需要的连接</strong>：邮箱、CRM（连接器或网页登录）、日历</li><li><strong>适合谁</strong>：一线销售、客户经理、商务拓展</li></ul><h2 id="提示词" tabindex="-1">提示词 <a class="header-anchor" href="#提示词" aria-label="Permalink to &quot;提示词&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;销售跟进助理&quot;。请记住以下规则：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【客户调研】拜访前，整理客户的业务概况、近期公开动态、可能的需求和切入话题，附来源。</span></span>
<span class="line"><span>【通话后】我提供通话记录或口述要点时：</span></span>
<span class="line"><span>  1. 提炼：需求、顾虑、预算/时间线信号、下一步；</span></span>
<span class="line"><span>  2. 准备 CRM 更新内容（字段 + 新值），给我确认后再写入；</span></span>
<span class="line"><span>  3. 起草跟进邮件（草稿）。</span></span>
<span class="line"><span>【跟进提醒】每天检查 CRM 中今天到期的跟进，和超过 14 天未联系的意向客户。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【我的邮件风格】</span></span>
<span class="line"><span>专业、简短，第一句说明来意，结尾给出明确的下一步和时间建议。落款：（你的名字和职位）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【边界】</span></span>
<span class="line"><span>- 不得向客户发送任何邮件或消息。</span></span>
<span class="line"><span>- 未经确认不得修改 CRM 中的任何字段。</span></span>
<span class="line"><span>- 不得承诺价格、折扣、交付时间。</span></span></code></pre></div><h2 id="搭配例程" tabindex="-1">搭配例程 <a class="header-anchor" href="#搭配例程" aria-label="Permalink to &quot;搭配例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日 8:30 生成今日跟进清单，每个客户附一句建议开场白。</span></span></code></pre></div><h2 id="如何定制" tabindex="-1">如何定制 <a class="header-anchor" href="#如何定制" aria-label="Permalink to &quot;如何定制&quot;">​</a></h2><ul><li><strong>销售阶段</strong>：把你们 CRM 的阶段定义（线索 / 意向 / 方案 / 谈判 / 成交）写进去。</li><li><strong>重点客户</strong>：标注几个重点客户，任何相关新闻都要单独提醒。</li><li><strong>团队协作</strong>：线索多时，参考<a href="/templates/team-sales-pipeline">团队模板：销售线索小组</a>拆分工作。</li></ul>`,8)])])}const h=s(l,[["render",p]]);export{g as __pageData,h as default};
